// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        // grant the role to the actor (deployer has TIMELOCK_ADMIN_ROLE)
        c.grantRole(PROPOSER_ROLE, actor);
        assertTrue(c.hasRole(PROPOSER_ROLE, actor), "setup: actor holds role");

        // general rule: an account may always renounce its OWN role; afterwards it no longer holds it
        vm.prank(actor);
        try c.renounceRole(PROPOSER_ROLE, actor) {
            assertTrue(!c.hasRole(PROPOSER_ROLE, actor), "self-renounce removes role");
        } catch {
            assertTrue(false, "self-renounce must never revert");
        }
    }
}
